import pyomo.environ as pyo

DATA = {
    "depts": ["X1", "X2", "X3"],
    "cost": {"X1": 50000, "X2": 60000, "X3": 70000},
    "min_staff": {"X1": 2, "X2": 3, "X3": 5},
    "max_staff": {"X1": 6, "X2": 4, "X3": 5},
    "total_max": 10,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.DEPTS = pyo.Set(initialize=d["depts"])

    def staff_bounds(m, i):
        return (0, d["max_staff"][i])

    model.staff = pyo.Var(
        model.DEPTS,
        domain=pyo.NonNegativeIntegers,
        bounds=staff_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.staff[i] for i in m.DEPTS)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def total_cap_rule(m):
        return sum(m.staff[i] for i in m.DEPTS) <= d["total_max"]

    model.total_cap = pyo.Constraint(rule=total_cap_rule)

    def min_staff_rule(m, i):
        return m.staff[i] >= d["min_staff"][i]

    model.min_staff = pyo.Constraint(model.DEPTS, rule=min_staff_rule)

    return model

